source = inspect.getsource(ExecutionHarness)
lines = source.splitlines()
found = False
for i, line in enumerate(lines):
    if 'except Exception as e' in line or 'except Exception as err' in line:
        # Check subsequent lines for usage of 'e' outside the except block or before assignment
        # Simple heuristic: look for 'e' usage in the next 5 lines
        for j in range(i+1, min(i+10, len(lines))):
            if 'e' in lines[j] and 'except' not in lines[j] and 'def' not in lines[j]:
                # Check if it's a standalone 'e' or part of a variable name
                import re
                if re.search(r'(?<![a-zA-Z0-9_])e(?![a-zA-Z0-9_])', lines[j]):
                    found = True
                    break
    if found:
        break
if found:
    print('PROBE_SUCCESS: Potential UnboundLocalError pattern detected')
else:
    print('PROBE_FAIL: No obvious pattern detected')

