from hae.evaluation.harness import ExecutionHarness
source = inspect.getsource(ExecutionHarness)
lines = source.splitlines()
found = False
for i, line in enumerate(lines):
    if 'GateResult' in line and 'e' in line:
        # Check if 'e' is used in a way that might be unbound
        if re.search(r'(?<![a-zA-Z0-9_])e(?![a-zA-Z0-9_])', line):
            # Check if 'e' is defined in the current scope
            scope_start = i
            for k in range(i-1, max(i-20, 0), -1):
                if 'def ' in lines[k] or 'class ' in lines[k]:
                    scope_start = k
                    break
            scope_text = ' '.join(lines[scope_start:i+1])
            if 'as e' not in scope_text and 'e =' not in scope_text:
                found = True
                break
if found:
